    // Thread identifiers (1‑D grid)
    // ------------------------------------------------------------------
    .reg .u32   %tid, %ctaid, %ntid;
    mov.u32     %tid, %tid.x;        // threadIdx.x
    mov.u32     %ctaid, %ctaid.x;    // blockIdx.x
    mov.u32     %ntid, %ntid.x;      // blockDim.x

    // global linear thread id
    mad.lo.u32  %tid, %ntid, %ctaid, %tid;

    // ------------------------------------------------------------------
    // Fixed problem dimensions (as per the reference script)
    // ------------------------------------------------------------------
    .const .u32 BATCH      = 64;
    .const .u32 CHANNELS   = 128;
    .const .u32 INPUT_LEN  = 65536;
    .const .u32 OUTPUT_LEN = 65537;

