    .reg .u32   %total;
    mul.lo.u32  %total, BATCH, CHANNELS;
    mul.lo.u32  %total, %total, OUTPUT_LEN;

    // Exit if thread id exceeds total work
    .reg .pred %p_exit;
    setp.ge.u32 %p_exit, %tid, %total;
    @%p_exit ret;

    // ------------------------------------------------------------------
    // Decompose linear index into (b, c, out_pos)
    // ------------------------------------------------------------------
    .reg .u32   %prod_bc, %b, %rem, %c, %out_pos;
    mul.lo.u32  %prod_bc, CHANNELS, OUTPUT_LEN;          // CHANNELS * OUTPUT_LEN

    div.u32     %b, %tid, %prod_bc;                     // batch index
    mul.lo.u32  %rem, %b, %prod_bc;
    sub.u32     %rem, %tid, %rem;                       // remainder within batch

    div.u32     %c, %rem, OUTPUT_LEN;                   // channel index
    mul.lo.u32  %out_pos, %c, OUTPUT_LEN;
    sub.u32     %out_pos, %rem, %out_pos;               // position in output length

