    // Compute start index of the pooling window in the input
    // start = out_pos * S - P
    // ------------------------------------------------------------------
    .reg .s32   %start;
    cvt.s32.u32 %start, %out_pos;
    mul.lo.s32  %start, %start, %S;
    sub.s32     %start, %start, %P;

    // ------------------------------------------------------------------
    // Accumulate over the kernel window (fp32)
    // ------------------------------------------------------------------
    .reg .f32   %sum;
    mov.f32     %sum, 0f00000000;   // 0.0f

    .reg .u32   %k;
    mov.u32     %k, 0;

LOOP_START:
    .reg .pred %p_continue;
    setp.lt.u32 %p_continue, %k, %K;
    @!%p_continue bra LOOP_END;

