    setp.ge.s32 %p_in_range, %in_idx, 0;
    @!%p_in_range bra SKIP_LOAD;
    setp.lt.s32 %p_in_range, %in_idx, INPUT_LEN;
    @!%p_in_range bra SKIP_LOAD;

    // Compute linear index into input:
    // idx = ((b * CHANNELS + c) * INPUT_LEN) + in_idx
    .reg .u32   %bc_idx, %lin_idx;
    mul.lo.u32  %bc_idx, %b, CHANNELS;
    add.u32     %bc_idx, %bc_idx, %c;
    mul.lo.u32  %lin_idx, %bc_idx, INPUT_LEN;
    add.u32     %lin_idx, %lin_idx, %in_idx;

