    ld.global.f16 %val_f16, [%addr];
    .reg .f32   %val_f32;
    cvt.f32.f16 %val_f32, %val_f16;
    add.f32     %sum, %sum, %val_f32;

SKIP_LOAD:
    add.u32     %k, %k, 1;
    bra         LOOP_START;

LOOP_END:
    // ------------------------------------------------------------------
    // Compute average = sum / K
    // ------------------------------------------------------------------
    .reg .f32   %K_f32;
    cvt.f32.u32 %K_f32, %K;
    div.f32     %sum, %sum, %K_f32;

    // Convert back to half
    .reg .f16   %out_f16;
    cvt.f16.f32 %out_f16, %sum;

    // ------------------------------------------------------------------
    // Store result to output tensor
    // ------------------------------------------------------------------
    // out_idx = ((b * CHANNELS + c) * OUTPUT_LEN) + out_pos
    .reg .u32   %out_lin_idx;
    mul.lo.u32  %bc_idx, %b, CHANNELS;
    add.u32     %bc_idx, %bc_idx, %c;
    mul.lo.u32  %out_lin_idx, %bc_idx, OUTPUT_LEN;
    add.u32     %out_lin_idx, %out_lin_idx, %out_pos;

    cvt.u64.u32 %addr, %out_lin_idx;
    mul.lo.u64  %addr, %addr, 2;
    add.u64     %addr, %addr, %output;

    st.global.f16 [%addr], %out_f16;

