# ----------------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew:
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "avg_pool1d_fp16"
        self.K = kernel_size
        self.S = stride
        self.P = padding

        # Fixed dimensions from the reference script
        self.batch = 64
        self.channels = 128
        self.input_len = 65536
        self.output_len = (self.input_len + 2 * self.P - self.K) // self.S + 1

        # Launch configuration (1‑D grid)
        self.block_dim = 256
        total_threads = self.batch * self.channels * self.output_len
        self.grid_dim = (total_threads + self.block_dim - 1) // self.block_dim

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
