            device=x.device,
        )

        # Build argument list for the PTX kernel
        args = [
            x.data_ptr(),
            out.data_ptr(),
            self.K,
            self.S,
            self.P,
        ]

        # Launch kernel
        ptx_launch(
            self.module,
            self.kernel_name,
            (self.grid_dim,),
            (self.block_dim,),
            args,
        )
        return out
